     *
     * @return The range for the Contours (z-axis).
     */
    @Override
    public Range getContourDataRange() {
        Range result = null;
        ContourDataset data = getDataset();
        if (data != null) {
            Range h = getDomainAxis().getRange();
            Range v = getRangeAxis().getRange();
            result = this.visibleRange(data, h, v);
        }
        return result;
    }

